-- Reading the history (UC-069, redix-api #86). Every History line keeps the trace id of the request that wrote it (#150), so the lines one
-- request wrote are told from the next request's, whatever the clock says (R11, D3); a line written before has '' and stands alone.
ALTER TABLE history ADD COLUMN trace_id TEXT NOT NULL DEFAULT '';
-- «سجلي» reads the lines of one login (R9).
CREATE INDEX ix_history_table_name_record_id ON history (table_name, record_id);

-- SeeProjectHistory, «يرى سجل المشروع», opens a project's history (R7, D1). SQLite cannot change a CHECK in place, so project_permissions is
-- rebuilt as SQLite's documentation does it, with user_projects, the view reading it, dropped and made again around the rebuild.
DROP VIEW user_projects;
CREATE TABLE project_permissions_new (
    id TEXT NOT NULL,
    project_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    permission TEXT CHECK (length(permission) <= 30) NOT NULL,
    PRIMARY KEY (id),
    FOREIGN KEY (project_id) REFERENCES projects (id),
    FOREIGN KEY (user_id) REFERENCES users (id),
    CHECK ((permission='GenerateReports' OR permission='SeeReports' OR permission='MoveMoney' OR permission='ApproveEntries' OR permission='AttachFiles' OR permission='RemoveApprovedEntries' OR permission='DeleteEntries' OR permission='ManageAnyEntry' OR permission='RecordEntries' OR permission='ChargeAnyAccount' OR permission='AddSupplier' OR permission='ManageSettings' OR permission='ManageStructure' OR permission='ManageProject' OR permission='SeeChosenCapital' OR permission='SeeAllCapital' OR permission='ReadProject' OR permission='ManageUsers' OR permission='ApproveProjects' OR permission='SeeProjectHistory') AND permission<>'ApproveProjects')
) STRICT;
DROP TABLE project_permissions;
ALTER TABLE project_permissions_new RENAME TO project_permissions;
CREATE UNIQUE INDEX ix_project_permissions_project_id_user_id_permission ON project_permissions (project_id, user_id, permission);
CREATE INDEX ix_project_permissions_user_id ON project_permissions (user_id);

CREATE VIEW user_projects AS
SELECT project_permissions.user_id,
       project_permissions.project_id,
       projects.name AS project_name,
       json_group_array(project_permissions.permission) AS permissions,
       COALESCE((SELECT role_name FROM project_role_names
                 WHERE project_role_names.project_id = project_permissions.project_id AND project_role_names.user_id = project_permissions.user_id), '') AS role_name,
       (SELECT json_group_array(partner_id) FROM (SELECT partner_id FROM chosen_partners
                 WHERE chosen_partners.project_id = project_permissions.project_id AND chosen_partners.user_id = project_permissions.user_id ORDER BY id)) AS partner_ids,
       EXISTS (SELECT 1 FROM inactive_members
               WHERE inactive_members.project_id = project_permissions.project_id AND inactive_members.user_id = project_permissions.user_id) AS is_inactive
FROM project_permissions JOIN projects ON projects.id = project_permissions.project_id
GROUP BY project_permissions.user_id, project_permissions.project_id;

-- The words of «سجل المشروع» and «سجلي» (D5): what was done, to what, in one shape for every line. «ما قمت به» gives way to the person
-- chip's «أنا» (R13, D6).
DELETE FROM translations WHERE translation_key_id = (SELECT id FROM translation_keys WHERE key = 'history.mine');
DELETE FROM translation_keys WHERE key = 'history.mine';


